 * the subject on the 50px content inset; quiet row actions appear on the
 * current, hovered or focus-within row and stay Tab-reachable; the trailing
 * slot (a full date, a status word) sits about 25px from the pane edge.
 */
.context-pane {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
}

.context-pane:focus {
  outline: none;
}

/* Coverage line with one quiet action on its trailing side (Reminders, Drafts). */
.context-coverage {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-right: 24px;
}

.context-coverage .cached-coverage {
  padding-right: 0;
}

.context-coverage .drawer-quiet {
  margin-right: -8px;
}

/* In-flow recovery and error lines above the rows, on the content inset. */
.draft-notices:not(:empty) {
  padding: 6px 24px 0 50px;
}

/* Drafts rows: the recipient is the row's button and keeps a bounded width; the subject takes the rest. */
.drafts-pane .context-row-main {
  flex: 0 1 16em;
}

.drafts-pane .context-row-secondary {
  flex: 1 1 0;
  padding: 0 12px;
}

.draft-subject:not(.drawer-empty) {
  color: var(--text-primary);
}

.draft-reply {
  color: var(--text-secondary);
}

.draft-date {
  min-width: 4em;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.context-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.context-list:focus {
  outline: none;
}

.context-item {
  margin: 0;
  padding: 0;
}

.context-row {
  cursor: pointer;
}

.context-row-lead {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
}

.context-row-main {
  display: flex;
  flex: 1 1 0;
  align-items: center;
  min-width: 0;
  min-height: 36px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.context-row-main:hover:not(:disabled) {
  background: transparent;
}

/* The row's fill and lavender bar are its focus indicator, as in the Inbox. */
.context-row-main:focus-visible {
  outline: none;
}

.context-row-primary,
.context-subject {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-subject {
  display: block;
  font-weight: var(--weight-strong);
}

.context-row-secondary {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-secondary);
}

.context-row-secondary:empty {
  display: none;
}

.context-row-actions {
  display: flex;
  flex: none;
  align-items: center;
  gap: 6px;
  opacity: 0;
}

.context-row-actions:empty {
  display: none;
}

.context-row:is(.focused, :hover, :focus-within) .context-row-actions {
  opacity: 1;
}

/* Quiet Ash ghosts on a lit row: the fill already equals the hover fill, so a hovered button takes a ring. */
.context-row-actions .drawer-quiet:hover:not(:disabled) {
  box-shadow: inset 0 0 0 1px var(--text-secondary);
}

.context-row-trailing {
  display: flex;
  flex: none;
  align-items: center;
  gap: 12px;
  color: var(--text-secondary);
  white-space: nowrap;
}

.context-date {
  min-width: 12em;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.context-phase {
  min-width: 6em;
}

/* An exception under its row: Coral or Amber, on the content inset. */
.context-row-note {
  margin: 0;
  padding: 0 24px 6px 50px;
  font-size: var(--type-body);
  line-height: var(--leading-ui);
}

/* Label: the month of a compact date is uppercase on screen only ("6 NOV");
