    listeners[0]!();
    await flushPromises();
    expect(model.counts.value).toEqual({ pending: 1, returned: 1, history: 0 });
    model.deactivate();
    expect(unsubscribe).toHaveBeenCalledTimes(1);
    scope.stop();
    expect(unsubscribe).toHaveBeenCalledTimes(1);
  });

